import { useSyncExternalStore } from 'react';

// 1. We create a subscription function for a browser API (External Store)
function subscribe(callback) {
  window.addEventListener('online', callback);
  window.addEventListener('offline', callback);

  // Cleanup function
  return () => {
    window.removeEventListener('online', callback);
    window.removeEventListener('offline', callback);
  };
}

// 2. We create a function to get the current snapshot of the data
function getSnapshot() {
  return navigator.onLine;
}

export default function NetworkStatus() {
  // 3. We use the hook!
  // React will automatically re-render this component if the snapshot changes.
  const isOnline = useSyncExternalStore(subscribe, getSnapshot);

  return (
    <div>
      <h2>System Status</h2>
      <p>You are currently: <b>{isOnline ? '🟢 Online' : '🔴 Offline'}</b></p>
    </div>
  );
}
